#!/usr/bin/env bash
set -euo pipefail

BASE_BRANCH="codex/google-drive-storage-20261101"
REQUIRED_BASE_COMMIT="2377a4295a3981e48a90c22d439811df87fad1b5"
TARGET_BRANCH="${1:-feature/kosmora-google-drive-complete-20261101}"

echo "[1/6] Fetching origin/$BASE_BRANCH..."
git fetch origin "$BASE_BRANCH"

if ! git cat-file -e "$REQUIRED_BASE_COMMIT^{commit}" 2>/dev/null; then
  echo "ERROR: Base commit $REQUIRED_BASE_COMMIT not found after fetching $BASE_BRANCH" >&2
  exit 1
fi

echo "[2/6] Creating branch $TARGET_BRANCH from $REQUIRED_BASE_COMMIT..."
git checkout -B "$TARGET_BRANCH" "$REQUIRED_BASE_COMMIT"

echo "[3/6] Extracting Google Drive OAuth controller, archive builder, restore, and routes..."
python3 - <<'INNER_PY'
import base64, io, tarfile
payload = base64.b64decode('''''')
with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as tf:
    tf.extractall(".")

# Wire GoogleDrivePanel in apps/web/src/app/personal-settings/page.tsx if not yet wired
page_path = "apps/web/src/app/personal-settings/page.tsx"
with open(page_path, "r", encoding="utf-8") as f:
    page_text = f.read()
if "GoogleDrivePanel" not in page_text:
    page_text = page_text.replace(
        'import PrivacyPanel from "./privacy-panel";',
        'import PrivacyPanel from "./privacy-panel";\nimport GoogleDrivePanel from "./google-drive-panel";'
    )
    page_text = page_text.replace(
        "          <PrivacyPanel />",
        "          <GoogleDrivePanel />\n          <PrivacyPanel />"
    )
    with open(page_path, "w", encoding="utf-8") as f:
        f.write(page_text)

# Wire shared GoogleDriveBackups + GoogleDriveController in apps/api/src/server.ts
srv_path = "apps/api/src/server.ts"
with open(srv_path, "r", encoding="utf-8") as f:
    srv_text = f.read()
if "createConfiguredGoogleDriveStack" not in srv_text:
    srv_text = srv_text.replace(
        'import { googleDrivePrivacyAdapter } from "./cloud-storage/google-drive-privacy.js";',
        'import { createConfiguredGoogleDriveStack } from "./cloud-storage/index.js";'
    )
    srv_text = srv_text.replace(
        "  ownerPrivacy.register(googleDrivePrivacyAdapter(database.sqlite));\n  app = buildApp({",
        "  const googleDriveStack = createConfiguredGoogleDriveStack({ db: database.sqlite, privacy: ownerPrivacy });\n  ownerPrivacy.register(googleDriveStack.privacyAdapter);\n  app = buildApp({\n    googleDriveController: googleDriveStack.controller,"
    )
    with open(srv_path, "w", encoding="utf-8") as f:
        f.write(srv_text)

# Wire registerGoogleDriveRoutes in apps/api/src/app.ts
app_path = "apps/api/src/app.ts"
with open(app_path, "r", encoding="utf-8") as f:
    app_text = f.read()
if "registerGoogleDriveRoutes" not in app_text:
    app_text = app_text.replace(
        'import { registerPrivacyRoutes } from "./account-settings/privacy/routes.js";',
        'import { registerPrivacyRoutes } from "./account-settings/privacy/routes.js";\nimport { registerGoogleDriveRoutes, type GoogleDriveController } from "./cloud-storage/index.js";'
    )
    app_text = app_text.replace(
        "  ownerPrivacy?: OwnerPrivacyCoordinator;",
        "  ownerPrivacy?: OwnerPrivacyCoordinator;\n  googleDriveController?: GoogleDriveController;"
    )
    app_text = app_text.replace(
        "  if (dependencies.accountStore && dependencies.ownerPrivacy)\n    registerPrivacyRoutes(app, dependencies.ownerPrivacy, dependencies.accountStore, identityFor);",
        "  if (dependencies.accountStore && dependencies.ownerPrivacy)\n    registerPrivacyRoutes(app, dependencies.ownerPrivacy, dependencies.accountStore, identityFor);\n  if (dependencies.googleDriveController)\n    registerGoogleDriveRoutes(app, dependencies.googleDriveController, identityFor);"
    )
    with open(app_path, "w", encoding="utf-8") as f:
        f.write(app_text)
INNER_PY

echo "[4/6] Running Google Drive integration smoke & unit tests..."
node scripts/integration-google-drive-smoke.mjs

echo "[5/6] Committing changes on $TARGET_BRANCH..."
git add apps/api/src/cloud-storage apps/api/src/app.ts apps/api/src/server.ts apps/web/src/app/personal-settings apps/api/test/google-drive-complete.test.ts scripts/integration-google-drive-smoke.mjs docs/handoff/KOSMORA_GOOGLE_DRIVE_COMPLETE_2026-11-01_RU.md
git commit -m "feat(cloud-storage): complete Google Drive OAuth controller, multipart archive builder, privacy quiesce, and transactional restore"

echo "[6/6] Pushing branch and opening Draft PR against $BASE_BRANCH..."
git push -u origin "$TARGET_BRANCH"
if command -v gh >/dev/null 2>&1; then
  gh pr create --draft \
    --base "$BASE_BRANCH" \
    --head "$TARGET_BRANCH" \
    --title "feat(cloud-storage): complete Google Drive OAuth controller, multipart archive builder, and transactional restore" \
    --body-file docs/handoff/KOSMORA_GOOGLE_DRIVE_COMPLETE_2026-11-01_RU.md
else
  echo "gh CLI not installed; open Draft PR from $TARGET_BRANCH into $BASE_BRANCH on GitHub."
fi
